import graphql.annotations.processor.exceptions.GraphQLAnnotationsException;
import graphql.schema.GraphQLDirective;
import graphql.schema.GraphQLType;
import org.junit.Test;
import org.mockito.Mockito;

import java.lang.annotation.Annotation;
import java.lang.reflect.Method;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class DirectivesBuilderTest {

    @Test
    public void buildNoDirectivesTest() {
        DirectivesBuilder builder = new DirectivesBuilder(mock(Method.class), null);
        GraphQLDirective[] result = builder.build();
        assertNotNull(result);
        assertEquals(0, result.length);
    }

    @Test(expected = GraphQLAnnotationsException.class)
    public void buildWithInvalidDirectiveAnnotationTest() {
        Method mockMethod = Mockito.mock(Method.class);
        when(mockMethod.getAnnotations()).thenReturn(new Annotation[]{new InvalidAnnotation()});
        DirectivesBuilder builder = new DirectivesBuilder(mockMethod, null);
        builder.build();
    }

    @Test
    public void buildWithValidDirectiveAnnotationTest() {
        Method mockMethod = Mockito.mock(Method.class);
        when(mockMethod.getAnnotations()).thenReturn(new Annotation[]{new ValidAnnotation()});
        DirectivesBuilder builder = new DirectivesBuilder(mockMethod, null);
        GraphQLDirective[] result = builder.build();
        assertNotNull(result);
        assertEquals(1, result.length);
    }

    @Test
    public void buildWithMultipleDirectiveAnnotationsTest() {
        Method mockMethod = Mockito.mock(Method.class);
        when(mockMethod.getAnnotations()).thenReturn(new Annotation[]{new ValidAnnotation(), new ValidAnnotation()});
        DirectivesBuilder builder = new DirectivesBuilder(mockMethod, null);
        GraphQLDirective[] result = builder.build();
        assertNotNull(result);
        assertEquals(2, result.length);
    }

}

class ValidAnnotation implements Annotation {

    @Override
    public Class<? extends Annotation> annotationType() {
        return GraphQLDirectives.class;
    }
}

class InvalidAnnotation implements Annotation {

    @Override
    public Class<? extends Annotation> annotationType() {
        return this.getClass();
    }
}
